/* The panel page: one query in one market, told as verdict → evidence → context. Tabs share one header. */
window.SerpPanel = (() => {
  'use strict';
  const U = window.SerpUI;
  const { I, esc, D, T, DT, pct, n, plural } = U;
  const enc = encodeURIComponent;
  const TABS = [['summary', 'Summary'], ['history', 'History'], ['compare', 'Compare'], ['ai', 'AI Overview'], ['evidence', 'Evidence'], ['settings', 'Settings']];
  const human = (v) => U.cap(String(v || 'unknown').replace(/_/g, ' '));
  let ctx = null;

  async function render(c, id, requested) {
    ctx = c; const { $, link } = ctx;
    const tab = { overview: 'summary', review: 'evidence' }[requested] || (TABS.some(([k]) => k === requested) ? requested : 'summary');
    let panel;
    try { panel = await ctx.panelData(id); } catch (error) { $('main').innerHTML = `<div class="page"><div class="notice err"><span class="ib">${I('alert')}</span><div class="t"><b>Panel not found</b><p>${esc(error.message)}</p></div></div></div>`; return; }
    const rep = await ctx.report(); const q = rep.queries.find((x) => x.id === id) || panel.analysis;
    const peers = ctx.sortQueries(rep.queries).filter((x) => U.kind(x.status) === U.kind(q.status)); const at = peers.findIndex((x) => x.id === id);
    const prev = peers[at - 1]; const next = peers[at + 1];
    const rejected = (panel.observations || []).filter((o) => U.REJECTED.includes(o.quality?.state)).length;
    const counts = { history: (panel.timeline || []).length || '', ai: panel.citations?.observed || '', evidence: q.status === 'review' ? 'decision' : rejected ? `${rejected} rejected` : '' };
    const running = ctx.projectRow()?.running;
    $('main').innerHTML = `<div class="page" style="gap:0">
      <div class="crumbs"><a href="${link.view('panels')}">Panels</a><span class="sep">/</span><span class="dim nowrap">${esc(q.query)}</span><span class="grow"></span>${peers.length > 1 ? `<span class="hide-sm">${at + 1} of ${peers.length} ${esc(U.word(q.status).toLowerCase())}</span>${prev ? `<a class="icon-btn boxed" href="${link.panel(prev.id, tab === 'summary' ? '' : tab)}" title="Previous (K)" aria-label="Previous panel">${I('up')}</a>` : ''}${next ? `<a class="icon-btn boxed" href="${link.panel(next.id, tab === 'summary' ? '' : tab)}" title="Next (J)" aria-label="Next panel">${I('down')}</a>` : ''}<span class="hide-sm">${U.kbd('J / K')}</span>` : ''}</div>
      <div class="ptitle"><h1>${esc(q.query)}</h1>${U.pill(q, true)}<span class="chip">${esc(U.marketText(panel.target.search, ctx.engines()))}</span><span class="chip">every ${q.settings?.interval_hours ?? 24} h</span>${q.group ? `<span class="tag">${esc(q.group)}</span>` : ''}<span class="grow"></span><button class="btn" type="button" id="p-collect"${running ? ' disabled' : ''}>${I('collect')}<span>${running ? 'Collecting…' : 'Collect now'}</span></button><div class="switcher-wrap" style="position:relative"><button class="icon-btn boxed" type="button" id="p-more" aria-haspopup="menu" aria-expanded="false" aria-label="More actions">${I('more')}</button><div class="menu" id="p-more-menu" role="menu" hidden style="left:auto;right:0;width:240px"><a role="menuitem" href="/api/p/${enc(ctx.state.project)}/export/report.json" download="serp-drift-report.json">${I('download')}Export report JSON</a>${q.status === 'watch' && !ctx.seen(q) ? `<button role="menuitem" type="button" id="p-seen">${I('eye')}Mark as seen</button>` : ''}<button role="menuitem" type="button" id="p-pause">${I(q.paused ? 'play' : 'pause')}${q.paused ? 'Resume collection' : 'Pause collection'}</button><a role="menuitem" href="${link.panel(id, 'settings')}">${I('settings')}Panel settings</a></div></div></div>
      <nav class="tabs" aria-label="Panel">${TABS.map(([k, l]) => `<a href="${link.panel(id, k === 'summary' ? '' : k)}"${k === tab ? ' aria-current="page"' : ''}>${l}${counts[k] ? `<small>${esc(counts[k])}</small>` : ''}</a>`).join('')}</nav>
      <div id="tab" class="col" style="padding-top:20px"></div></div>`;
    $('p-collect').addEventListener('click', () => ctx.collect([id], true));
    const more = $('p-more'); const menu = $('p-more-menu');
    more.addEventListener('click', (e) => { e.stopPropagation(); menu.hidden = !menu.hidden; more.setAttribute('aria-expanded', String(!menu.hidden)); });
    $('p-seen')?.addEventListener('click', () => ctx.markSeen({ q, pid: ctx.state.project }));
    $('p-pause').addEventListener('click', async () => { try { await ctx.api(ctx.P(`/panels/${enc(id)}/pause`), { method: 'POST', body: { paused: !q.paused } }); ctx.toast(q.paused ? 'Panel follows the schedule again.' : 'Panel paused. Stored captures stay.'); ctx.invalidate(); await ctx.loadStatus(); ctx.render(); } catch (error) { ctx.fail(error); } });
    ctx.state.keys = (e) => { if (e.key === 'j' && next) ctx.go(link.panel(next.id, tab === 'summary' ? '' : tab)); if (e.key === 'k' && prev) ctx.go(link.panel(prev.id, tab === 'summary' ? '' : tab)); };
    const body = $('tab');
    if (tab === 'history') return historyTab(panel, q, body);
    if (tab === 'compare') return compare(panel, q, body);
    if (tab === 'ai') return ai(panel, q, body);
    if (tab === 'evidence') return window.SerpReview.evidence(ctx, panel, q, body);
    if (tab === 'settings') return settings(panel, q, body);
    return summary(panel, q, body, rep);
  }

  // --- summary ----------------------------------------------------------------------------------------------------------
  function summary(panel, q, body, rep) {
    const { link } = ctx; const id = panel.target.id; const k = U.kind(q.status); const th = q.settings?.drift_threshold ?? 35;
    const lat = q.latest || {}; const cmp = q.comparison; const site = panel.project?.site; const s = U.siteTrack(q);
    const since = (panel.events || []).filter((e) => e.kind === 'status_change').sort((a, b) => b.at.localeCompare(a.at))[0];
    const next = U.nextCapture(q); const isToday = next && next.slice(0, 10) === new Date().toISOString().slice(0, 10);
    const obs = panel.observations || []; const rej = obs.filter((o) => U.REJECTED.includes(o.quality?.state)).length; const acc = obs.filter((o) => o.quality?.state === 'accepted').length;
    const need = Math.max(0, (q.settings?.baseline_size ?? 3) - (q.baseline?.length ?? 0));
    const nextText = q.collection_ended ? 'No new capture will arrive; these are the final observations.' : k === 'watch' ? 'Becomes a review only if two spaced captures agree on an intent or page-fit change.' : k === 'review' ? (q.decision?.next_action || 'Record what you decide; the rationale stays attached to this change.') : k === 'building' ? `Scores start after ${plural(need || 1, 'more spaced capture')}.` : k === 'issue' ? (q.reasons || []).join(' ') : `Stays stable unless the score reaches the watch threshold of ${th}.`;
    const primary = k === 'review' ? `<a class="btn primary" href="${link.panel(id, 'evidence')}">Record decision</a>` : k === 'watch' && !ctx.seen(q) ? '<button class="btn primary" type="button" id="v-seen">Mark as seen</button>' : k === 'issue' ? `<button class="btn primary" type="button" id="v-retry">${I('collect')}Retry now</button>` : '';
    const reasons = (q.decision?.reasons || q.reasons || []).filter((r) => r && r !== 'Inspect the observed changes.');
    const verdictBody = [U.verdictText(q), k === 'review' || k === 'issue' ? '' : ''].filter(Boolean).join(' ') || q.decision?.next_action || '';
    const baseTop = lat.intent_distribution && q.baseline_intent && q.baseline_intent !== 'unknown' ? `${q.baseline_intent} ${Math.round((U.avgMix(q.baseline)[q.baseline_intent] || 0) * 100)} % → ${Math.round((lat.intent_distribution[q.baseline_intent] || 0) * 100)} %` : `${pct(lat.classified_coverage)} of rank weight classified`;
    const declared = panel.target.page;
    const contribs = cmp ? U.contributions(cmp.components, panel.weights) : null;
    const notes = cmp ? { url_turnover: `${(cmp.entered || []).length} of ${(lat.results || []).length} current results are new; ${(cmp.exited || []).length} left.`, intent: q.baseline_intent && lat.dominant_intent ? `${q.baseline_intent} → ${lat.dominant_intent}` : '', result_types: 'Mix of result formats against the baseline.', features: [...(cmp.features_added || []).map((f) => `${U.FEATURES[f] || f} appeared`), ...(cmp.features_removed || []).map((f) => `${U.FEATURES[f] || f} gone`)].join(', ') || 'Same features as the baseline.', rank_movement: cmp.components?.rank_movement == null ? 'No URL present in both sets.' : `${(cmp.rank_changes || []).length} shared URLs moved.` } : {};
    const cit = panel.citations || { hosts: [], captures: [] };
    const maxHost = Math.max(1, ...cit.hosts.slice(0, 5).map((h) => h.citations));
    const pts = (panel.timeline || []).filter((p) => U.capKind(p) !== 'x');
    const featCounts = {}; pts.forEach((p) => (p.features || []).forEach((f) => { featCounts[f] = (featCounts[f] || 0) + 1; }));
    const baseRank = new Map(); (q.baseline || []).forEach((b) => (b.results || []).forEach((r) => { const v = baseRank.get(r.url) || []; v.push(r.position); baseRank.set(r.url, v); }));
    const avg = (v) => v.reduce((a, b) => a + b, 0) / v.length;
    const exited = (cmp?.exited || []).map((u) => ({ url: u, pos: baseRank.has(u) ? avg(baseRank.get(u)) : null, r: (q.baseline || []).flatMap((b) => b.results || []).find((r) => r.url === u) })).sort((a, b) => (a.pos ?? 99) - (b.pos ?? 99));
    const mine = (u) => site && (U.host(u) === site || U.host(u).endsWith(`.${site}`));
    const moveOf = (r) => { if (!cmp) return ''; if ((cmp.entered || []).includes(r.url)) return `${I('external')}new`; const rc = (cmp.rank_changes || []).find((x) => x.url === r.url); if (rc) { const b = Math.round(rc.before * 10) / 10; return b === r.position ? '=' : `${b} → ${r.position}`; } return '='; };
    const resultRow = (r, out, pos) => `<div class="result"><button class="trow" type="button" style="width:100%;border:0;background:${mine(r.url) ? 'var(--surface-2)' : 'none'};text-align:left;cursor:pointer;grid-template-columns:44px minmax(0,1fr) 130px 100px 110px" aria-expanded="false"><span class="${out ? 'muted' : 'dim'} num">${pos ?? r.position}</span><span class="t"><span class="row"><b class="nowrap">${esc(r.title || r.url)}</b>${mine(r.url) ? '<span class="tag you">your site</span>' : ''}${declared?.url && U.hostPath(declared.url) === U.hostPath(r.url) ? '<span class="tag">declared page</span>' : ''}</span><small>${esc(U.hostPath(r.url))}</small></span><span class="hide-sm"><i class="sw ${esc(r.intent || 'unknown')}"></i><span class="dim">${esc(r.intent || 'unknown')}</span></span><span class="muted hide-sm">${esc(r.type && r.type !== 'unknown' ? r.type : '—')}</span><span class="right muted">${out ? `${pos} → out` : moveOf(r)}</span></button><div class="hidden" style="padding:0 18px 14px 62px;font-size:12.5px;color:var(--text-2);line-height:1.5"><p>${esc(r.snippet || 'No snippet returned.')}</p><ul style="margin:6px 0 0;padding-left:16px;color:var(--text-3)">${(r.evidence || []).map((line) => `<li>${esc(line)}</li>`).join('') || '<li>No decisive lexical evidence; the intent remains unknown.</li>'}</ul><a class="link" href="${U.safeUrl(r.url)}" target="_blank" rel="noopener noreferrer">Open the result ↗</a></div></div>`;
    body.innerHTML = `
      <section class="card verdict ${k}"><div><div class="eyebrow">${esc(U.word(q))}${since ? ` · since ${esc(DT(since.at))} UTC` : ''}</div><h2>${esc(q.decision?.title || U.word(q))}</h2>${verdictBody ? `<p>${esc(verdictBody)}</p>` : ''}${reasons.length && k !== 'stable' ? `<ul>${reasons.map((r) => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}</div>
        <div class="next"><span class="l">What happens next</span><b>${next ? `Next capture ${isToday ? 'today ' : `${D(next)} `}${T(next)} UTC` : q.collection_ended ? 'Collection ended' : 'No capture scheduled'}</b><p>${esc(nextText)}</p><div class="form-actions">${primary}<a class="btn" href="${link.panel(id, 'compare')}">${I('compare')}Compare</a></div></div></section>
      <div class="measures"><div><span class="l">${I('activity')}SERP change</span><b>${q.score == null ? 'Not ready' : `${Math.round(q.score)} / 100`}</b><span>Change index · watch at ${th}</span></div><div><span class="l">${I('target')}Intent</span><b>${esc(human(q.dimensions?.intent))}</b><span>${esc(baseTop)}</span></div><div><span class="l">${I('page')}Page fit</span><b>${declared ? esc(human(q.dimensions?.page_fit)) : 'No page declared'}</b><span>${declared ? `Declared ${esc(declared.intent || 'page')} · ${esc(U.pathOnly(declared.url))}` : site ? `Tracking ${esc(site)} automatically` : 'Declare a page in Settings'}</span></div><div><span class="l">${I('shield')}Data</span><b>${acc} accepted${rej ? ` · ${rej} rejected` : ''}</b><span>Search context ${esc(q.evidence?.quality?.provenance || 'unverified')}</span></div></div>
      <div class="with-rail">
        <div class="col">
          <div class="card pad"><div class="card-head"><h3>Score by capture</h3><span class="meta">${plural((panel.timeline || []).length, 'capture')}${pts.length ? ` · ${D(panel.timeline[0].captured_at)}–${D(panel.timeline[panel.timeline.length - 1].captured_at)}` : ''}</span><span class="grow"></span>${U.chartKey(panel.timeline)}</div>${U.chart(panel.timeline, q.settings, { height: 150 })}${rej ? `<p class="note">${plural(rej, 'capture')} returned results for another query or were excluded. They stay stored for audit but never count as evidence.</p>` : ''}</div>
          ${contribs ? `<div class="card pad"><div class="card-head"><h3>Why ${U.score(q.score)}</h3><span class="meta">points out of 100 · weights fixed and versioned</span></div>${U.contribBar(contribs, th)}<div class="table comp-table"><div class="thead" style="grid-template-columns:minmax(0,1fr) 70px 70px 60px"><span>Component</span><span class="right">Weight</span><span class="right">Distance</span><span class="right">Points</span></div>${contribs.map((cmpt, i) => `<div class="trow" style="grid-template-columns:minmax(0,1fr) 70px 70px 60px"><span><i class="sw ${cmpt.points ? `c${Math.min(4, contribs.filter((x) => x.points).indexOf(cmpt) + 1)}` : 'c0'}"></i><b style="font-weight:500">${esc(cmpt.label)}</b><span class="muted nowrap hide-sm">${esc(notes[cmpt.key] || '')}</span></span><span class="right dim num">${Math.round(cmpt.weight * 100)} %</span><span class="right dim num">${cmpt.distance == null ? 'n/a' : Math.round(cmpt.distance * 100)}</span><span class="right num"><b>${cmpt.points == null ? '0' : `+${cmpt.points.toFixed(1)}`}</b></span></div>`).join('')}<div class="trow" style="grid-template-columns:minmax(0,1fr) auto"><span><b>Change score</b></span><span class="muted">${q.score == null ? '' : `${Number(q.score).toFixed(1)} → shown as ${Math.round(q.score)} · watch at ${th}; a review needs a confirmed intent or page-fit change`}</span></div></div></div>` : ''}
          ${q.baseline?.length && lat.intent_distribution ? `<div class="card pad"><div class="card-head"><h3>Intent mix</h3><span class="meta">${pct(lat.classified_coverage)} of rank weight classified · lexical estimate, not measured intent</span></div>${U.mixHtml(U.avgMix(q.baseline), lat.intent_distribution, ['Baseline', 'Latest'], [`${plural(q.baseline.length, 'capture')} averaged`, D(lat.captured_at)])}</div>` : ''}
          ${lat.results?.length ? `<div class="card clip"><div class="card-head" style="padding:16px 18px 10px"><h3>Top 10 now</h3><span class="meta">${esc(DT(lat.captured_at))} UTC${cmp ? ' · compared with the baseline window' : ''}</span></div><div class="table" id="results"><div class="thead" style="grid-template-columns:44px minmax(0,1fr) 130px 100px 110px"><span>#</span><span>Result</span><span class="hide-sm">Intent</span><span class="hide-sm">Type</span><span class="right">vs baseline</span></div>${lat.results.map((r) => resultRow(r, false)).join('')}
            ${exited.length ? `<button class="xhead" type="button" id="x-toggle" aria-expanded="${exited.length <= 6}">${I('down')}${plural(exited.length, 'result')} left the top 10<span class="meta">· baseline rank shown</span></button><div id="x-list"${exited.length <= 6 ? '' : ' class="hidden"'}>${exited.map((x) => resultRow(x.r || { url: x.url, title: U.hostPath(x.url) }, true, x.pos == null ? '—' : Math.round(x.pos * 10) / 10)).join('')}</div>` : ''}</div></div>` : ''}
        </div>
        <div class="rail">
          <div class="card pad"><div class="card-head">${I('globe')}<h3>Your site</h3><span class="grow"></span><span class="meta">${esc(site || 'not set')}</span></div><div class="big-v">${s.now ? `#${s.now}` : s.dropped ? 'Not in the top 10' : 'Not in the top 10'}</div><p class="note" style="color:var(--text-2);font-size:12.5px">${esc(s.now ? `${U.hostPath(s.url)}${s.moved ? `, up from #${s.from}` : ''}${s.urlChanged ? `. Replaced ${U.hostPath(s.urlChanged)} as your ranking URL.` : ''}` : s.dropped ? `${U.hostPath(s.url)} held #${s.heldFrom}${s.heldTo !== s.heldFrom ? `–#${s.heldTo}` : ''} for ${plural(s.heldCount, 'capture')} and left on ${DT(s.leftAt)} UTC.` : site ? `No ${site} URL ${s.partial ? 'in the latest capture' : 'ranked in the accepted captures'}.` : 'Set the project site in Settings to track your ranking URL automatically.')}</p>${site && pts.length && !s.partial ? `<div class="stack" style="gap:6px">${U.cellsHtml(U.positions(q, 10))}<div class="row" style="font-size:11px;color:var(--text-3)"><span class="grow">${esc(D(pts[Math.max(0, pts.length - 10)]?.captured_at))}</span><span>${esc(D(pts[pts.length - 1]?.captured_at))}</span></div></div>` : ''}</div>
          <div class="card pad"><div class="card-head">${I('quote')}<h3>AI Overview</h3><span class="grow"></span><span class="meta">${cit.observed || 0} of ${cit.total || 0}</span></div>${cit.observed ? `<div class="stats" style="grid-template-columns:1fr 1fr;grid-auto-flow:row"><div><b style="font-size:20px">${cit.site_cited}</b><span>times ${esc(site || 'your site')} was cited</span></div><div><b style="font-size:20px">${cit.references_per_overview ?? '—'}</b><span>references per Overview</span></div></div><div class="note">Most cited hosts</div><div class="stack" style="gap:6px">${cit.hosts.slice(0, 5).map((h) => U.hbar(h.host, h.citations, maxHost, { mine: Boolean(h.mine) })).join('')}</div><a class="link" href="${link.panel(id, 'ai')}" style="font-size:12.5px">Read the latest Overview →</a>` : `<p class="note">${lat.ai_overview_status === 'not_available' ? 'Google reports no AI Overview for this query.' : lat.ai_overview_status === 'requires_followup' ? 'Deferred by Google and not expanded (expansion is off or failed).' : lat.ai_overview_status === 'not_applicable' ? 'This engine has no AI Overview.' : 'No AI Overview observed yet.'}</p>`}</div>
          <div class="card pad"><div class="card-head">${I('features')}<h3>SERP features</h3></div><div class="stack" style="gap:4px">${(lat.features || []).map((f) => `<div class="feature-row"><span>${esc(U.FEATURES[f] || f)}</span>${(cmp?.features_added || []).includes(f) ? '<span class="tag new">appeared</span>' : ''}<span class="grow"></span><span class="n">${featCounts[f] || 0} / ${pts.length}</span></div>`).join('')}${(cmp?.features_removed || []).map((f) => `<div class="feature-row"><span class="muted">${esc(U.FEATURES[f] || f)}</span><span class="tag">gone</span><span class="grow"></span><span class="n">${featCounts[f] || 0} / ${pts.length}</span></div>`).join('')}${!(lat.features || []).length && !(cmp?.features_removed || []).length ? '<p class="note">No tracked features in the latest capture.</p>' : ''}</div></div>
          <div class="card pad"><div class="card-head">${I('info')}<h3>About this panel</h3></div><dl class="kv"><dt>Baseline</dt><dd>${q.baseline?.length ? `${esc(D(q.baseline[0].captured_at))}${q.baseline.length > 1 ? `–${esc(D(q.baseline[q.baseline.length - 1].captured_at))}` : ''} · ${plural(q.baseline.length, 'capture')}` : 'building'}${q.baseline_from ? ` · anchored ${esc(D(q.baseline_from))}` : ''}</dd><dt>Confirmation</dt><dd>${plural(q.settings?.confirmations ?? 2, 'spaced capture')}</dd><dt>Interval</dt><dd>${q.settings?.interval_hours ?? 24} h · ${plural((panel.timeline || []).length, 'capture')}</dd><dt>Classifier</dt><dd>${esc(q.evidence?.classifier || 'rules')} · ${pct(lat.classified_coverage)} coverage</dd><dt>Identity</dt><dd class="num">${esc((panel.target.identity || '').slice(0, 12))}</dd>${q.paused ? '<dt>Collection</dt><dd>paused</dd>' : ''}</dl></div>
        </div>
      </div>`;
    body.querySelectorAll('.result > button').forEach((b) => b.addEventListener('click', () => { const open = b.getAttribute('aria-expanded') === 'true'; b.setAttribute('aria-expanded', String(!open)); b.nextElementSibling.classList.toggle('hidden', open); }));
    ctx.$('x-toggle')?.addEventListener('click', (e) => { const b = e.currentTarget; const open = b.getAttribute('aria-expanded') === 'true'; b.setAttribute('aria-expanded', String(!open)); ctx.$('x-list').classList.toggle('hidden', open); });
    ctx.$('v-seen')?.addEventListener('click', () => ctx.markSeen({ q, pid: ctx.state.project }));
    ctx.$('v-retry')?.addEventListener('click', () => ctx.collect([id], true));
  }

  // --- history -----------------------------------------------------------------------------------------------------------
  function historyTab(panel, q, body) {
    const { link, $ } = ctx; const traj = panel.trajectories || { captures: [], urls: [] }; const th = q.settings?.drift_threshold ?? 35;
    let range = 'all'; let showRejected = true;
    const scoreAt = new Map((panel.timeline || []).map((p) => [p.captured_at, p.score]));
    body.innerHTML = `<div class="toolbar"><div class="seg" id="h-range">${[['all', `All · ${(panel.timeline || []).length}`], ['7', '7 days'], ['3', '3 days']].map(([v, l]) => `<button type="button" data-r="${v}" aria-pressed="${v === range}">${l}</button>`).join('')}</div><label class="field inline" style="font-weight:400"><button class="toggle small" type="button" id="h-rej" role="switch" aria-checked="true" aria-label="Show rejected captures"><i></i></button><span class="dim">Show rejected captures</span></label><span class="grow"></span></div>
      <div class="card pad"><div class="card-head"><h3>Score by capture</h3><span class="grow"></span>${U.chartKey(panel.timeline)}</div><div id="h-chart"></div></div>
      <div class="card pad"><div class="card-head"><h3>URL trajectories</h3><span class="meta">${plural(traj.urls.length, 'URL')} seen in ${plural(traj.captures.length, 'accepted capture')} · position per capture</span><span class="grow"></span><span class="chart-key"><span><i style="background:var(--band-1)"></i>1–3</span><span><i style="background:var(--band-2)"></i>4–6</span><span><i style="background:var(--band-3)"></i>7–10</span><span><i style="background:none;box-shadow:inset 0 0 0 1px var(--line-strong)"></i>left</span><span>${I('arrowUp')}entered</span></span></div><div class="matrix-wrap" id="h-matrix"></div></div>
      <div class="card clip"><div class="card-head" style="padding:16px 18px 10px"><h3>Change log</h3><span class="meta">what changed since the previous capture · score is against the baseline</span></div><div id="h-log"></div></div>`;
    const draw = () => {
      const cut = range === 'all' ? 0 : Date.now() - Number(range) * 86400000;
      const pts = (panel.timeline || []).filter((p) => new Date(p.captured_at).getTime() >= cut && (showRejected || U.capKind(p) !== 'x'));
      $('h-chart').innerHTML = U.chart(pts, q.settings, { height: 130, maxCols: 60 });
      const idx = traj.captures.map((c, i) => [c, i]).filter(([c]) => new Date(c).getTime() >= cut).map(([, i]) => i);
      const caps = idx.map((i) => traj.captures[i]);
      const lastIdx = (u) => { for (let j = idx.length - 1; j >= 0; j--) if (u.positions[idx[j]] != null) return [j, u.positions[idx[j]]]; return [-1, 99]; };
      const urls = traj.urls.filter((u) => idx.some((i) => u.positions[i] != null)).sort((a, b) => { const [ja, pa] = lastIdx(a); const [jb, pb] = lastIdx(b); return jb - ja || pa - pb; }).slice(0, 80);
      const cols = `grid-template-columns:minmax(220px,330px) repeat(${Math.max(1, caps.length)},minmax(46px,1fr))`;
      let prevDay = '';
      $('h-matrix').innerHTML = caps.length ? `<div class="matrix"><div class="mh" style="${cols}"><span style="align-items:flex-start">URL</span>${caps.map((c) => { const d = c.slice(0, 10); const show = d !== prevDay; prevDay = d; const hot = (scoreAt.get(c) ?? 0) >= th; return `<span class="${hot ? 'hot' : ''}" title="${esc(DT(c))} UTC${scoreAt.get(c) != null ? ` · score ${Math.round(scoreAt.get(c))}` : ''}">${show ? esc(D(c)) : '&nbsp;'}<small>${esc(T(c))}</small></span>`; }).join('')}</div>${urls.map((u) => `<div class="mr${u.mine ? ' mine' : ''}" style="${cols}"><span class="u" title="${esc(u.title || u.url)}"><span>${esc(U.hostPath(u.url))}</span>${u.mine ? '<span class="tag you">your site</span>' : ''}</span>${idx.map((i, j) => { const p = u.positions[i]; const before = j > 0 ? u.positions[idx[j - 1]] : (i > 0 ? u.positions[i - 1] : null); if (p == null) return `<span class="cl">${before != null && j > 0 ? '<i class="left"></i>' : ''}</span>`; const band = p <= 3 ? 'b1' : p <= 6 ? 'b2' : 'b3'; return `<span class="cl"><i class="${band}" title="#${p} on ${esc(DT(traj.captures[i]))} UTC">${before == null && (j > 0 || i > 0) ? I('arrowUp') : ''}${p}</i></span>`; }).join('')}</div>`).join('')}</div>${traj.urls.length > 80 ? `<p class="note">Showing 80 of ${traj.urls.length} URLs.</p>` : ''}` : '<div class="empty">No accepted captures in this range.</div>';
    };
    const changes = (panel.changes || []).slice(0, 20);
    $('h-log').innerHTML = changes.map((c) => { const bits = [c.ranking_url_changed ? `ranking URL ${U.hostPath(c.site_before?.url || '')} → ${U.hostPath(c.site_after?.url || '')}` : '', c.entered.length ? `${c.entered.length} entered` : '', c.exited.length ? `${c.exited.length} left` : '', c.moved?.length ? `${c.moved.length} moved` : '', c.site_before && !c.site_after ? `${U.hostPath(c.site_before.url)} left (#${c.site_before.position} → out)` : '', !c.site_before && c.site_after ? `${U.hostPath(c.site_after.url)} entered at #${c.site_after.position}` : '', c.site_before?.position && c.site_after?.position && c.site_before.position !== c.site_after.position && !c.ranking_url_changed ? `your URL #${c.site_before.position} → #${c.site_after.position}` : '', ...(c.features_added || []).map((f) => `${U.FEATURES[f] || f} appeared`), ...(c.features_removed || []).map((f) => `${U.FEATURES[f] || f} gone`), c.intent_before !== c.intent_after ? `intent ${c.intent_before} → ${c.intent_after}` : ''].filter(Boolean); const sc = scoreAt.get(c.captured_at); const ev = (panel.events || []).find((e) => e.kind === 'status_change' && Math.abs(new Date(e.at) - new Date(c.captured_at)) < 600000); return `<div class="log-row" style="grid-template-columns:120px 40px minmax(0,1fr) auto"><span class="when">${esc(DT(c.captured_at))}</span><span class="num ${sc != null && sc >= th ? 'strong' : 'dim'}" style="${sc != null && sc >= th ? 'color:var(--watch-text)' : ''}">${sc == null ? '—' : Math.round(sc)}</span><span class="what" style="color:${bits.length > 2 ? 'var(--text)' : 'var(--text-2)'}">${esc(c.quiet ? 'No change against the previous capture.' : U.cap(bits.join(' · ')))}</span><span>${ev ? `<span class="pill ${U.kind(ev.payload?.after)}"><i></i>${esc(U.word(ev.payload?.before))} → ${esc(U.word(ev.payload?.after))}</span>` : ''}</span></div>`; }).join('') || '<div class="empty">Changes appear from the second capture on.</div>';
    $('h-range').addEventListener('click', (e) => { const b = e.target.closest('button[data-r]'); if (!b) return; range = b.dataset.r; $('h-range').querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', String(x === b))); draw(); });
    $('h-rej').addEventListener('click', () => { showRejected = !showRejected; $('h-rej').setAttribute('aria-checked', String(showRejected)); draw(); });
    draw();
  }

  // --- compare -------------------------------------------------------------------------------------------------------------
  function compare(panel, q, body) {
    const { $, api, P, route } = ctx; const id = panel.target.id; const caps = panel.captures || []; const params = route().params; const site = panel.project?.site;
    if (!caps.length) { body.innerHTML = '<div class="card empty"><b>Nothing to compare yet.</b>Compare needs at least one capture.</div>'; return; }
    const presets = [['baseline-latest', 'Baseline → latest', { preset: 'baseline' }, { preset: 'latest' }], ['weeks', 'Last 7 days → previous 7', { preset: 'previous_7_days' }, { preset: 'last_7_days' }], ['date', 'Before / after a date', null, null], ['captures', 'Two captures', null, null]];
    let mode = params.get('mode') || 'baseline-latest'; let left = { preset: 'baseline' }, right = { preset: 'latest' };
    if (params.get('a')) { try { left = JSON.parse(params.get('a')); right = JSON.parse(params.get('b')); mode = 'custom'; } catch {} }
    const presetLabel = { baseline: 'Baseline window', latest: 'Latest capture', last_7_days: 'Last 7 days', previous_7_days: 'Previous 7 days', last_30_days: 'Last 30 days', first_week: 'First week' };
    body.innerHTML = `<div class="toolbar"><div class="seg" id="c-presets">${presets.map(([k, l]) => `<button type="button" data-mode="${k}" aria-pressed="${k === mode}">${l}</button>`).join('')}</div></div><div id="c-sides"></div><div id="c-result" class="col"><div class="card empty">Comparing…</div></div>`;
    const side = (name, spec) => `<div class="card pad" style="gap:6px"><div class="row"><span class="num-badge">${name}</span><span class="muted">${esc(spec.preset ? presetLabel[spec.preset] || spec.preset : spec.capture ? 'One capture' : 'Date range')}</span><span class="grow"></span><a class="link" href="#" data-change="${name}">Change</a></div><b style="font-size:15px" data-val="${name}">…</b><span class="dim" data-sub="${name}"></span><div class="hidden stack" data-form="${name}" style="padding-top:8px"><label class="field">One capture<select class="input" data-capture="${name}"><option value="">—</option>${caps.map((c) => `<option value="${esc(c)}">${esc(DT(c))} UTC</option>`).join('')}</select></label><div class="form-grid" style="grid-template-columns:1fr 1fr"><label class="field">From<input class="input" type="date" data-from="${name}"></label><label class="field">To<input class="input" type="date" data-to="${name}"></label></div><div><button class="btn small" type="button" data-apply="${name}">Apply</button></div></div></div>`;
    const drawSides = () => {
      $('c-sides').innerHTML = `<div class="row" style="align-items:stretch;gap:12px"><div class="grow">${side('A', left)}</div><div style="display:grid;place-items:center"><span class="icon-btn boxed" aria-hidden="true">${I('arrowRight')}</span></div><div class="grow">${side('B', right)}</div></div>`;
      $('c-sides').querySelectorAll('[data-change]').forEach((a) => a.addEventListener('click', (e) => { e.preventDefault(); $('c-sides').querySelector(`[data-form="${a.dataset.change}"]`).classList.toggle('hidden'); }));
      $('c-sides').querySelectorAll('[data-apply]').forEach((b) => b.addEventListener('click', () => { const nm = b.dataset.apply; const cap = $('c-sides').querySelector(`[data-capture="${nm}"]`).value; const from = $('c-sides').querySelector(`[data-from="${nm}"]`).value; const to = $('c-sides').querySelector(`[data-to="${nm}"]`).value; const spec = cap ? { capture: cap } : { from: from || undefined, to: to || undefined }; if (nm === 'A') left = spec; else right = spec; mode = 'custom'; $('c-presets').querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', 'false')); run(); }));
    };
    $('c-presets').addEventListener('click', (e) => { const b = e.target.closest('button[data-mode]'); if (!b) return; mode = b.dataset.mode; $('c-presets').querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', String(x === b))); const p = presets.find((x) => x[0] === mode); if (p[2]) { left = p[2]; right = p[3]; } else if (mode === 'date') { const mid = caps[Math.floor(caps.length / 2)] || ''; left = { from: caps[0]?.slice(0, 10), to: mid.slice(0, 10) }; right = { from: mid.slice(0, 10), to: caps[caps.length - 1]?.slice(0, 10) }; } else { left = { capture: caps[Math.max(0, caps.length - 2)] }; right = { capture: caps[caps.length - 1] }; } run(); });
    async function run() {
      drawSides(); const out = $('c-result'); out.innerHTML = '<div class="card empty">Comparing…</div>';
      try {
        const data = await api(P(`/panels/${enc(id)}/compare`), { method: 'POST', body: { left, right } });
        history.replaceState(null, '', `${location.pathname}#/p/${enc(ctx.state.project)}/panel/${enc(id)}?tab=compare&a=${enc(JSON.stringify(left))}&b=${enc(JSON.stringify(right))}`);
        const label = (d) => `${D(d.from)}${d.from !== d.to ? ` – ${D(d.to)}` : ` ${T(d.to)} UTC`} · ${plural(d.captures, 'capture')}${d.captures > 1 ? ', averaged' : ''}`;
        $('c-sides').querySelector('[data-val="A"]').textContent = label(data.left); $('c-sides').querySelector('[data-sub="A"]').textContent = `intent ${data.left.dominant_intent}`;
        $('c-sides').querySelector('[data-val="B"]').textContent = label(data.right); $('c-sides').querySelector('[data-sub="B"]').textContent = `intent ${data.right.dominant_intent}`;
        const [capA, capB] = await Promise.all([api(P(`/panels/${enc(id)}/captures/${enc(data.left.to)}`)), api(P(`/panels/${enc(id)}/captures/${enc(data.right.to)}`))]);
        const aRes = capA.snapshot.results; const bRes = capB.snapshot.results; const aPos = new Map(aRes.map((r) => [r.url, r])); const bPos = new Map(bRes.map((r) => [r.url, r]));
        const mine = (u) => site && (U.host(u) === site || U.host(u).endsWith(`.${site}`));
        const th = q.settings?.drift_threshold ?? 35; const contribs = U.contributions(data.components, panel.weights); const scoreV = contribs.reduce((a, c) => a + (c.points || 0), 0);
        const urls = [...bRes.map((r) => r.url), ...aRes.map((r) => r.url).filter((u) => !bPos.has(u))];
        out.innerHTML = `<div class="card" style="display:grid;grid-template-columns:260px minmax(0,1fr)"><div class="stack" style="padding:20px 22px;border-right:1px solid var(--line);gap:6px"><span class="muted">Change score A → B</span><div class="row" style="align-items:flex-end;gap:6px"><b style="font-size:44px;font-weight:600;letter-spacing:-1.5px;line-height:1">${Math.round(data.score)}</b><span class="muted" style="font-size:14px">/ 100</span></div><p class="note" style="color:var(--text-2)">${Number(data.score).toFixed(1)} before rounding. Same arithmetic as the alert, so nothing here can disagree with the status. Watch at ${th}.</p></div>
            <div class="table comp-table" style="padding:6px 22px">${contribs.map((c2) => `<div class="trow" style="grid-template-columns:130px 80px minmax(0,1fr) 110px 56px"><span><b style="font-weight:500">${esc(c2.label)}</b></span><span class="muted">${Math.round(c2.weight * 100)} % weight</span><span><span class="track" style="width:100%;height:6px"><i style="width:${c2.distance == null ? 0 : Math.round(c2.distance * 100)}%;background:var(--text-2)"></i></span></span><span class="right muted">${c2.distance == null ? 'n/a · no URL in both' : `distance ${Math.round(c2.distance * 100)}`}</span><span class="right num"><b>${c2.points == null ? '0' : `+${c2.points.toFixed(1)}`}</b></span></div>`).join('')}</div></div>
          <div class="card clip"><div class="card-head" style="padding:16px 18px 10px"><h3>Aligned results</h3><span class="meta">exact URL matching · ${data.entered.length} entered · ${data.exited.length} left</span></div><div class="table"><div class="thead" style="grid-template-columns:minmax(0,1fr) 56px 56px 140px 220px"><span>Result</span><span class="right">A</span><span class="right">B</span><span class="hide-sm">Change</span><span class="hide-sm">Intent A → B</span></div>${urls.map((u) => { const a = aPos.get(u); const b = bPos.get(u); const change = !a ? `entered at ${b.position}` : !b ? `left from ${a.position}` : a.position === b.position ? 'same' : `${a.position} → ${b.position}`; const ia = a?.intent; const ib = b?.intent; return `<div class="trow" style="grid-template-columns:minmax(0,1fr) 56px 56px 140px 220px;${mine(u) ? 'background:var(--surface-2)' : ''}"><span class="row"><span class="nowrap ${b ? '' : 'dim'}">${esc(U.hostPath(u))}</span>${mine(u) ? '<span class="tag you">your site</span>' : ''}</span><span class="right num ${a ? 'dim' : 'faint'}">${a ? a.position : '—'}</span><span class="right num ${b ? 'dim' : 'faint'}">${b ? b.position : '—'}</span><span class="hide-sm dim">${esc(change)}</span><span class="hide-sm">${ia ? `<i class="sw ${esc(ia)}"></i><span class="muted">${esc(ia)}</span>` : '<span class="faint">—</span>'}${ib && ib !== ia ? `<span class="faint">→</span><i class="sw ${esc(ib)}"></i><span class="dim">${esc(ib)}</span>` : ''}</span></div>`; }).join('')}</div></div>
          <div class="card pad"><div class="card-head"><h3>SERP features</h3></div><div class="chips">${data.features_added.map((f) => `<button type="button" aria-pressed="true">${I('plus')}${esc(U.FEATURES[f] || f)}</button>`).join('')}${(capB.snapshot.features || []).filter((f) => !data.features_added.includes(f)).map((f) => `<button type="button">${esc(U.FEATURES[f] || f)}</button>`).join('')}${data.features_removed.map((f) => `<button type="button" style="text-decoration:line-through;color:var(--text-3)">${esc(U.FEATURES[f] || f)}</button>`).join('') || ''}</div></div>`;
      } catch (error) { out.innerHTML = `<div class="notice err"><span class="ib">${I('alert')}</span><div class="t"><b>Could not compare</b><p>${esc(error.message)}</p></div></div>`; }
    }
    run();
  }

  // --- AI Overview ---------------------------------------------------------------------------------------------------------
  function ai(panel, q, body) {
    const { $, api, P, route } = ctx; const c = panel.citations || { captures: [], hosts: [] }; const site = panel.project?.site; const id = panel.target.id;
    const withOverview = c.captures.filter((r) => r.status === 'observed').map((r) => r.captured_at);
    let at = route().params.get('at') || withOverview[withOverview.length - 1] || null;
    const max = Math.max(1, ...c.hosts.map((h) => h.citations));
    const recent = c.captures.slice(-12); const topHosts = c.hosts.slice(0, 5).map((h) => h.host); if (site && !topHosts.includes(site) && !c.hosts.slice(0, 5).some((h) => h.mine)) topHosts.push(site);
    if (!c.observed) { body.innerHTML = `<div class="card empty"><b>${c.total ? `No AI Overview in ${plural(c.total, 'capture')}.` : 'No captures yet.'}</b>${ctx.state.status?.settings?.ai_overview === 'skip' ? 'Overview expansion is off for this project; turn it on in Settings → Collection (one extra request per capture).' : 'Google shows Overviews for some queries only.'}</div>`; return; }
    body.innerHTML = `<div class="stats"><div><b>${c.observed}<small> / ${c.total}</small></b><span>captures had an AI Overview</span></div><div><b>${c.site_cited}</b><span>cited ${esc(site || 'your site')}</span></div>${panel.target.page ? `<div><b>${c.page_cited}</b><span>cited the declared page</span></div>` : ''}<div><b>${c.references_per_overview ?? '—'}</b><span>references per Overview</span></div></div>
      <div class="with-rail" style="grid-template-columns:420px minmax(0,1fr)">
        <div class="col" style="gap:16px"><div class="card pad"><div class="card-head"><h3>Cited hosts</h3><span class="grow"></span><span class="meta">Overviews citing</span></div><div class="stack" style="gap:6px">${c.hosts.slice(0, 10).map((h) => U.hbar(h.host, h.citations, max, { mine: Boolean(h.mine) })).join('')}${site && !c.hosts.some((h) => h.mine) ? `<div class="hbar mine" style="border-top:1px solid var(--line);padding-top:8px;margin-top:4px"><span class="l"><span>${esc(site)}</span><span class="tag you">your site</span></span><span></span><span class="v muted" style="font-weight:400">never cited</span></div>` : ''}</div></div>
          <div class="card pad"><div class="card-head"><h3>Citations over time</h3><span class="grow"></span><span class="meta">${esc(D(recent[0]?.captured_at))} → ${esc(D(recent[recent.length - 1]?.captured_at))}</span></div><div class="stack" style="gap:8px">${topHosts.map((h) => `<div class="row" style="gap:10px"><span class="nowrap ${h === site ? 'strong' : 'dim'}" style="width:130px;font-size:12px">${esc(h)}</span><span class="dots">${recent.map((r) => `<i class="${(r.cited_hosts || []).includes(h) ? 'on' : ''}" title="${esc(DT(r.captured_at))}"></i>`).join('')}</span></div>`).join('')}</div><p class="note">Filled: cited in that capture's Overview.</p></div>
          <div class="card clip"><div class="table"><div class="thead" style="grid-template-columns:110px 1fr 60px 80px"><span>Capture</span><span>Overview</span><span class="right">Refs</span><span class="right">Your site</span></div>${[...c.captures].reverse().slice(0, 20).map((r) => `<a class="trow" href="#" data-at="${esc(r.captured_at)}" style="grid-template-columns:110px 1fr 60px 80px${r.captured_at === at ? ';background:var(--surface-2);box-shadow:inset 2px 0 0 var(--blue)' : ''}"><span class="dim">${esc(DT(r.captured_at))}</span><span class="muted">${r.status === 'observed' ? 'yes' : r.status === 'not_available' ? 'none' : r.status === 'requires_followup' ? 'deferred' : '—'}</span><span class="right num dim">${r.status === 'observed' ? r.references : '—'}</span><span class="right ${r.site_cited || r.page_cited ? 'strong' : 'muted'}">${r.status === 'observed' ? (r.site_cited || r.page_cited ? 'cited' : 'no') : '—'}</span></a>`).join('')}</div></div></div>
        <div class="card pad reader" id="ai-reader"><div class="skeleton" style="width:50%"></div></div>
      </div>`;
    body.querySelectorAll('[data-at]').forEach((row) => row.addEventListener('click', (e) => { e.preventDefault(); at = row.dataset.at; body.querySelectorAll('[data-at]').forEach((x) => { const on = x.dataset.at === at; x.style.background = on ? 'var(--surface-2)' : ''; x.style.boxShadow = on ? 'inset 2px 0 0 var(--blue)' : ''; }); load(); }));
    async function load() {
      const reader = $('ai-reader'); if (!reader || !at) return;
      try {
        const data = await api(P(`/panels/${enc(id)}/captures/${enc(at)}`));
        const ov = data.ai_overview; const results = data.snapshot.results; const idx = withOverview.indexOf(at);
        const nav = `<div class="seg small">${idx > 0 ? `<button type="button" data-nav="${esc(withOverview[idx - 1])}">‹ ${esc(DT(withOverview[idx - 1]))}</button>` : ''}<button type="button" aria-pressed="true">${idx === withOverview.length - 1 ? 'Latest' : esc(DT(at))}</button>${idx >= 0 && idx < withOverview.length - 1 ? `<button type="button" data-nav="${esc(withOverview[idx + 1])}">${esc(DT(withOverview[idx + 1]))} ›</button>` : ''}</div>`;
        const head = `<div class="card-head"><h3>Overview text</h3><span class="meta">${esc(DT(at))} UTC${ov ? ` · ${plural((ov.reference_links || []).length, 'reference')}` : ''}</span><span class="grow"></span>${nav}</div>`;
        if (!ov) { reader.innerHTML = `${head}<p class="note">${data.snapshot.ai_overview_status === 'observed' ? 'The full text of this Overview was not stored.' : 'No Overview in this capture.'}</p>`; bind(); return; }
        const refs = ov.reference_links || [];
        const sup = (x) => (x.reference_indexes || []).length ? `<sup>${x.reference_indexes.map((i) => i + 1).join(' ')}</sup>` : '';
        const block = (b) => { const text = b.answer || b.text || b.snippet || ''; if (b.type === 'header') return `<h4>${esc(text)}</h4>`; if ((b.type || '').includes('list')) return `<ul>${(b.items || b.list || []).map((li) => `<li>${typeof li === 'string' ? esc(li) : li.code ? `<code>${esc(li.code)}</code>` : esc(li.answer || li.title || li.text || '')}${typeof li === 'string' ? '' : sup(li)}</li>`).join('')}</ul>`; if (b.code) return `<pre><code>${esc(b.code)}</code></pre>`; return `<p>${esc(text)}${sup(b)}</p>`; };
        const rank = (u) => results.find((x) => U.hostPath(x.url) === U.hostPath(u))?.position;
        reader.innerHTML = `${head}<div class="body">${(ov.text_blocks || []).map(block).join('')}</div><div class="refs">${refs.map((ref, i) => { const mine = site && (U.host(ref.link) === site || U.host(ref.link).endsWith(`.${site}`)); const r = rank(ref.link); return `<div class="ref${mine ? ' mine' : ''}"><span class="n">${i + 1}</span><span><a href="${U.safeUrl(ref.link)}" target="_blank" rel="noopener noreferrer">${esc(ref.title || U.host(ref.link))}</a> <span class="u">${esc(U.hostPath(ref.link))}</span></span><span class="s">${mine ? 'your site' : ''}${r ? `${mine ? ' · ' : ''}ranks #${r}` : mine ? ' · not in top 10' : ''}</span></div>`; }).join('')}</div><p class="note">Text is stored as captured; references are resolved from Google's redirect URLs to their final addresses.</p>`;
        bind();
      } catch (error) { reader.innerHTML = `<div class="notice err"><span class="ib">${I('alert')}</span><div class="t"><b>Could not load the Overview</b><p>${esc(error.message)}</p></div></div>`; }
      function bind() { reader.querySelectorAll('[data-nav]').forEach((b) => b.addEventListener('click', () => { at = b.dataset.nav; load(); })); }
    }
    load();
  }

  // --- settings ------------------------------------------------------------------------------------------------------------
  function settings(panel, q, body) {
    const { $, api, P, link } = ctx; const t = panel.target; const s = panel.settings || {}; const site = panel.project?.site; const attempts = panel.attempts || [];
    const failed = attempts.filter((a) => !a.success).length; let intent = t.page?.intent || '';
    body.innerHTML = `<div style="max-width:760px" class="col"><form id="ps-form" class="col">
      <section class="form-section"><header><h2>Your page</h2><p>Optional. ${site ? `Without it the app tracks whichever ${esc(site)} URL ranks.` : 'Set the project site in project Settings to track your ranking URL automatically.'}</p></header><label class="field">Declared page URL<input class="input" type="url" name="page_url" value="${esc(t.page?.url || '')}" placeholder="https://${esc(site || 'example.com')}/page/"></label><div class="field">Intent this page serves<div class="chips" id="ps-intents">${U.INTENTS.slice(0, 4).map((i) => `<button type="button" data-intent="${i}" aria-pressed="${intent === i}"><i class="sw ${i}"></i>${i}</button>`).join('')}</div></div>${q.site?.url ? `<p class="note">Currently ranking: ${esc(U.hostPath(q.site.url))} at #${q.site.position}${t.page?.url && U.hostPath(t.page.url) !== U.hostPath(q.site.url) ? ', which differs from the declared page.' : '.'}</p>` : ''}</section>
      <section class="form-section"><header><h2>Keyword group</h2><p>Organize panels by topic, client work or content plan; the Panels table can filter by group.</p></header><label class="field">Group<input class="input" name="group" maxlength="80" value="${esc(s.group || '')}" placeholder="e.g. SEO foundations"></label></section>
      <section class="form-section"><header><h2>Baseline</h2><p>Scores are measured against the first ${q.settings?.baseline_size ?? 3} spaced captures after this date. Re-anchoring keeps every capture; only the reference changes, and the status returns to building.</p></header><div class="row wrap" style="gap:16px;align-items:flex-end"><label class="field" style="width:200px">Anchored from<input class="input" type="date" name="baseline_from" value="${esc((s.baseline_from || '').slice(0, 10))}"></label><span class="note" style="padding-bottom:8px">${q.baseline?.length ? `Baseline = ${q.baseline.map((b) => esc(D(b.captured_at))).join(', ')}` : 'Baseline not complete yet'}</span>${s.baseline_from ? '<button class="btn small" type="button" id="ps-clear">Use the first captures</button>' : ''}</div></section>
      <section class="form-section"><header><h2>Collection</h2></header><div class="switch-row"><span class="t"><b>Follow the project schedule</b><span>Every ${q.settings?.interval_hours ?? 24} h · pause here without removing the panel</span></span><button class="toggle" type="button" id="ps-pause" role="switch" aria-label="Follow the project schedule" aria-checked="${!q.paused}"><i></i></button></div><div class="switch-row"><span class="t"><b>Expand AI Overviews</b><span>Project-wide · up to one extra request per capture</span></span><a class="link" href="${link.view('settings')}?s=collection">${ctx.state.status?.settings?.ai_overview === 'expand' ? 'On' : 'Off'} · change</a></div></section>
      <section class="form-section"><header><h2>Identity</h2><p>Fixed after creation. Changing the query, engine, market or device starts a new panel, so different things are never compared.</p></header><dl class="kv"><dt>Engine</dt><dd>${esc(ctx.engines()[t.search.engine || 'google'] || t.search.engine)}</dd><dt>Country · language</dt><dd>${esc((t.search.gl || '').toUpperCase())} · ${esc(t.search.hl || '')}</dd><dt>Device · location</dt><dd>${esc(t.search.device || '—')} · ${esc(t.search.location || '—')}</dd><dt>Panel id</dt><dd class="mono">${esc(t.id)}</dd><dt>Identity</dt><dd class="mono">${esc(t.identity)}</dd><dt>Attempts</dt><dd>${plural(panel.captures.length, 'capture')} · ${plural(attempts.length, 'attempt')}, ${failed} failed${attempts[0] ? ` · last ${esc(DT(attempts[0].attempted_at))} UTC (${esc(attempts[0].code)})` : ''}</dd></dl></section>
      <div class="save-bar"><span class="t">${I('info')}Changes are written to monitor.toml and the workspace database.</span><button class="btn ghost" type="button" id="ps-discard">Discard</button><button class="btn primary" type="button" id="ps-save">Save changes</button></div>
      <section class="form-section"><header><h2>Remove panel</h2><p>Removes the panel from monitor.toml. Stored captures stay in the database. Type the query to confirm.</p></header><div class="row wrap"><input class="input" type="text" id="ps-confirm" placeholder="${esc(t.query)}" style="width:260px"><button class="btn danger" type="button" id="ps-remove" disabled>${I('trash')}Remove panel</button></div></section>
    </form></div>`;
    $('ps-intents').addEventListener('click', (e) => { const b = e.target.closest('button[data-intent]'); if (!b) return; intent = intent === b.dataset.intent ? '' : b.dataset.intent; $('ps-intents').querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', String(x.dataset.intent === intent))); });
    $('ps-confirm').addEventListener('input', () => { $('ps-remove').disabled = $('ps-confirm').value.trim() !== t.query; });
    $('ps-pause').addEventListener('click', async () => { const on = $('ps-pause').getAttribute('aria-checked') === 'true'; try { await api(P(`/panels/${enc(t.id)}/pause`), { method: 'POST', body: { paused: on } }); $('ps-pause').setAttribute('aria-checked', String(!on)); ctx.toast(on ? 'Panel paused.' : 'Panel follows the schedule again.'); ctx.invalidate(); } catch (error) { ctx.fail(error); } });
    $('ps-clear')?.addEventListener('click', async () => { try { await api(P(`/panels/${enc(t.id)}/baseline`), { method: 'POST', body: { from: null } }); ctx.toast('Baseline reset to the first captures.'); ctx.invalidate(); ctx.render(); } catch (error) { ctx.fail(error); } });
    $('ps-discard').addEventListener('click', () => { ctx.invalidate(); ctx.render(); });
    $('ps-save').addEventListener('click', async () => {
      const form = $('ps-form'); const url = form.elements.page_url.value.trim(); const from = form.elements.baseline_from.value; const group = form.elements.group.value.trim();
      try {
        if (url !== (t.page?.url || '') || intent !== (t.page?.intent || '')) await api(P(`/panels/${enc(t.id)}/page`), { method: 'POST', body: { page_url: url || null, intent: intent || null } });
        if (from !== (s.baseline_from || '').slice(0, 10)) await api(P(`/panels/${enc(t.id)}/baseline`), { method: 'POST', body: { from: from || null } });
        if (group !== (s.group || '')) await api(P(`/panels/${enc(t.id)}/group`), { method: 'POST', body: { group } });
        ctx.toast('Saved.'); ctx.invalidate(); await ctx.loadStatus(); ctx.render();
      } catch (error) { ctx.fail(error); }
    });
    $('ps-remove').addEventListener('click', async () => { try { await api(P(`/panels/${enc(t.id)}`), { method: 'DELETE' }); ctx.toast('Panel removed. Its captures stay in the database.'); ctx.invalidate(); await ctx.loadStatus(); ctx.go(link.view('panels')); } catch (error) { ctx.fail(error); } });
  }

  return { render };
})();
